import json
import time
import uuid

# 記憶體儲存筆記資料
notes = []

# 筆記模型驗證函數
def validate_note(note_data):
    if not isinstance(note_data, dict):
        return False

    title = note_data.get('title', '').strip()
    content = note_data.get('content', '').strip()

    # 檢查必要欄位
    if not title or not content:
        return False

    # 檢查長度限制
    if len(title) > 200 or len(content) > 10000:
        return False

    return True

# 產生唯一的筆記ID
def generate_note_id():
    return str(uuid.uuid4())

# 取得所有筆記
async def get_all_notes():
    return notes

# 建立新筆記
async def create_note(note_data):
    if not validate_note(note_data):
        return None

    note = {
        'id': generate_note_id(),
        'title': note_data['title'].strip(),
        'content': note_data['content'].strip(),
        'createdAt': time.time(),
        'updatedAt': time.time()
    }

    notes.append(note)
    return note

# 取得指定ID的筆記
async def get_note_by_id(note_id):
    for note in notes:
        if note['id'] == note_id:
            return note
    return None

# 更新指定ID的筆記
async def update_note(note_id, note_data):
    if not validate_note(note_data):
        return None

    for i, note in enumerate(notes):
        if note['id'] == note_id:
            notes[i]['title'] = note_data['title'].strip()
            notes[i]['content'] = note_data['content'].strip()
            notes[i]['updatedAt'] = time.time()
            return notes[i]

    return None

# 刪除指定ID的筆記
async def delete_note(note_id):
    global notes
    original_length = len(notes)
    notes = [note for note in notes if note['id'] != note_id]
    return len(notes) < original_length

def handle(method, path, body):
    try:
        # 解析請求體
        if body:
            data = json.loads(body.decode('utf-8'))
        else:
            data = {}

        # 路由處理
        if method == 'GET' and path == '/notes':
            # 取得所有筆記
            result = get_all_notes()
            return (200, result)

        elif method == 'POST' and path == '/notes':
            # 建立新筆記
            note = create_note(data)
            if note:
                return (201, note)
            else:
                return (400, {'error': '無效的筆記資料'})

        elif method == 'GET' and path.startswith('/notes/'):
            # 取得指定ID的筆記
            note_id = path.split('/')[-1]
            note = get_note_by_id(note_id)
            if note:
                return (200, note)
            else:
                return (404, {'error': '筆記不存在'})

        elif method == 'PUT' and path.startswith('/notes/'):
            # 更新指定ID的筆記
            note_id = path.split('/')[-1]
            note = update_note(note_id, data)
            if note:
                return (200, note)
            else:
                return (404, {'error': '筆記不存在'})

        elif method == 'DELETE' and path.startswith('/notes/'):
            # 刪除指定ID的筆記
            note_id = path.split('/')[-1]
            deleted = delete_note(note_id)
            if deleted:
                return (200, {'message': '筆記已刪除'})
            else:
                return (404, {'error': '筆記不存在'})

        else:
            return (404, {'error': '端點不存在'})

    except json.JSONDecodeError:
        return (400, {'error': '無效的JSON格式'})
    except Exception as e:
        return (500, {'error': '伺服器內部錯誤'})

