const noteForm = document.getElementById('noteForm');
const noteIdInput = document.getElementById('noteId');
const noteTitleInput = document.getElementById('noteTitle');
const noteContentInput = document.getElementById('noteContent');
const cancelEditBtn = document.getElementById('cancelEdit');
const searchInput = document.getElementById('searchInput');
const filterSelect = document.getElementById('filterSelect');
const notesList = document.getElementById('notesList');

let notes = [];

// 初始化應用程式
async function init() {
    await loadNotes();
    setupEventListeners();
}

// 載入筆記列表
async function loadNotes() {
    try {
        const response = await fetch('api/notes');
        if (response.ok) {
            notes = await response.json();
            renderNotes(notes);
        } else {
            console.error('無法載入筆記:', response.status);
        }
    } catch (error) {
        console.error('錯誤:', error);
    }
}

// 渲染筆記列表
function renderNotes(notesToRender) {
    notesList.innerHTML = '';

    if (notesToRender.length === 0) {
        notesList.innerHTML = '<p class="no-notes">目前沒有筆記</p>';
        return;
    }

    const notesContainer = document.createElement('div');
    notesContainer.className = 'notes-container';

    notesToRender.forEach(note => {
        const noteElement = document.createElement('div');
        noteElement.className = 'note-item';
        noteElement.innerHTML = `
            <h3>${escapeHtml(note.title)}</h3>
            <p class="content-preview">${escapeHtml(note.content.substring(0, 100))}${note.content.length > 100 ? '...' : ''}</p>
            <p class="timestamp">更新時間: ${new Date(note.updatedAt).toLocaleString('zh-TW')}</p>
            <div class="note-actions">
                <button onclick="editNote('${note.id}')">編輯</button>
                <button onclick="deleteNote('${note.id}')">刪除</button>
            </div>
        `;
        notesContainer.appendChild(noteElement);
    });

    notesList.appendChild(notesContainer);
}

// 搜尋和篩選筆記
function filterNotes() {
    const searchTerm = searchInput.value.toLowerCase();
    const filterType = filterSelect.value;

    let filteredNotes = notes.filter(note => 
        note.title.toLowerCase().includes(searchTerm) || 
        note.content.toLowerCase().includes(searchTerm)
    );

    switch (filterType) {
        case 'recent':
            filteredNotes.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
            break;
        case 'oldest':
            filteredNotes.sort((a, b) => new Date(a.updatedAt) - new Date(b.updatedAt));
            break;
    }

    renderNotes(filteredNotes);
}

// 新增筆記
async function createNote() {
    const title = noteTitleInput.value.trim();
    const content = noteContentInput.value.trim();

    if (!title || !content) {
        alert('請填寫標題和內容');
        return;
    }

    try {
        const response = await fetch('api/notes', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ title, content })
        });

        if (response.ok) {
            const newNote = await response.json();
            notes.push(newNote);
            resetForm();
            renderNotes(notes);
        } else {
            console.error('新增筆記失敗:', response.status);
        }
    } catch (error) {
        console.error('錯誤:', error);
    }
}

// 編輯筆記
async function editNote(id) {
    const note = notes.find(n => n.id === id);
    if (!note) return;

    noteIdInput.value = note.id;
    noteTitleInput.value = note.title;
    noteContentInput.value = note.content;

    noteForm.onsubmit = function(e) {
        e.preventDefault();
        updateNote(id);
    };

    cancelEditBtn.style.display = 'inline-block';
}

// 更新筆記
async function updateNote(id) {
    const title = noteTitleInput.value.trim();
    const content = noteContentInput.value.trim();

    if (!title || !content) {
        alert('請填寫標題和內容');
        return;
    }

    try {
        const response = await fetch(`api/notes/${id}`, {
            method: 'PUT',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ title, content })
        });

        if (response.ok) {
            const updatedNote = await response.json();
            const index = notes.findIndex(n => n.id === id);
            if (index !== -1) {
                notes[index] = updatedNote;
                resetForm();
                renderNotes(notes);
            }
        } else {
            console.error('更新筆記失敗:', response.status);
        }
    } catch (error) {
        console.error('錯誤:', error);
    }
}

// 刪除筆記
async function deleteNote(id) {
    if (!confirm('確定要刪除這筆筆記嗎？')) return;

    try {
        const response = await fetch(`api/notes/${id}`, {
            method: 'DELETE'
        });

        if (response.ok) {
            notes = notes.filter(note => note.id !== id);
            renderNotes(notes);
        } else {
            console.error('刪除筆記失敗:', response.status);
        }
    } catch (error) {
        console.error('錯誤:', error);
    }
}

// 重置表單
function resetForm() {
    noteIdInput.value = '';
    noteTitleInput.value = '';
    noteContentInput.value = '';
    noteForm.onsubmit = function(e) {
        e.preventDefault();
        createNote();
    };
    cancelEditBtn.style.display = 'none';
}

// 取消編輯
function cancelEdit() {
    resetForm();
}

// HTML轉義函數
function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

// 設定事件監聽器
function setupEventListeners() {
    noteForm.onsubmit = function(e) {
        e.preventDefault();
        createNote();
    };

    cancelEditBtn.onclick = cancelEdit;

    searchInput.addEventListener('input', filterNotes);
    filterSelect.addEventListener('change', filterNotes);
}

// 初始化應用程式
init();

