/* 重置和基礎樣式 */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    line-height: 1.6;
    color: #333;
    background-color: #f4f4f4;
}

.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 20px;
}

header {
    text-align: center;
    margin-bottom: 30px;
    padding: 20px;
    background-color: #fff;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}

h1 {
    color: #2c3e50;
}

/* 表單樣式 */
.note-form {
    background-color: #fff;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
    margin-bottom: 30px;
}

.note-form input,
.note-form textarea {
    width: 100%;
    padding: 10px;
    margin-bottom: 15px;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 16px;
}

.note-form textarea {
    height: 120px;
    resize: vertical;
}

.note-form button {
    background-color: #3498db;
    color: white;
    padding: 12px 20px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 16px;
    margin-right: 10px;
}

.note-form button:hover {
    background-color: #2980b9;
}

#cancelEdit {
    background-color: #e74c3c;
}

#cancelEdit:hover {
    background-color: #c0392b;
}

/* 搜尋和篩選區 */
.search-section {
    display: flex;
    gap: 10px;
    margin-bottom: 20px;
    background-color: #fff;
    padding: 15px;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}

#searchInput {
    flex: 1;
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 16px;
}

#filterSelect {
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 16px;
    background-color: white;
}

/* 筆記列表樣式 */
.notes-list {
    margin-top: 20px;
}

.notes-container {
    display: grid;
    gap: 20px;
}

.note-item {
    background-color: #fff;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
    transition: transform 0.2s;
}

.note-item:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 8px rgba(0,0,0,0.15);
}

.note-item h3 {
    color: #2c3e50;
    margin-bottom: 10px;
    font-size: 1.2em;
}

.content-preview {
    color: #555;
    margin-bottom: 10px;
    line-height: 1.4;
}

.timestamp {
    color: #7f8c8d;
    font-size: 0.9em;
    margin-bottom: 15px;
}

.note-actions {
    display: flex;
    gap: 10px;
}

.note-actions button {
    padding: 8px 12px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 14px;
}

.note-actions button:first-child {
    background-color: #f39c12;
    color: white;
}

.note-actions button:last-child {
    background-color: #e74c3c;
    color: white;
}

.no-notes {
    text-align: center;
    padding: 40px;
    background-color: #fff;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
    color: #7f8c8d;
}

/* 响应式設計 */
@media (max-width: 600px) {
    .container {
        padding: 10px;
    }

    .search-section {
        flex-direction: column;
    }

    .note-actions {
        flex-direction: column;
    }

    .note-item {
        padding: 15px;
    }
}
